import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const CONFIG = await (async()=>{
  try { const response=await fetch('/api/config',{cache:'no-store'}); if(response.ok)return await response.json(); } catch {}
  try { const response=await fetch(new URL('./config.json',import.meta.url),{cache:'no-store'}); if(response.ok)return await response.json(); } catch {}
  return window.FAMILY_CONFIG||{};
})();
const sb = CONFIG.url && CONFIG.anonKey ? createClient(CONFIG.url, CONFIG.anonKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } }) : null;
const views = { feed: ['ТОЛЬКО ДЛЯ СВОИХ', 'Наша лента'], chats: ['РАЗГОВОРЫ', 'Сообщения'], family: ['ОБЩЕЕ МЕСТО', 'Наш круг'], profile: ['ВАШЕ ПРОСТРАНСТВО', 'Мой профиль'], settings: ['ПРЕДПОЧТЕНИЯ', 'Настройки'] };
let session = null, profile = null, family = null, selectedChat = null, members = [], postImage = null, authIntent = null, initTask = null;
const pendingKey = 'warmCircleIntent';

function escapeHtml(s='') { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function toast(s) { const t=$('#toast'); t.textContent=s; t.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>t.classList.remove('show'),2600); }
function notify(s) { const n=$('#notice'); n.textContent=s; n.hidden=false; }
function clearNotice(){ $('#notice').hidden=true; }
function setAuth(html, progress=1) { $('#authStep').innerHTML=html; $('#authProgress').innerHTML=`<span style="width:${progress}%"></span>`; }
function showAuth() { $('#app').hidden=true; $('#authScreen').hidden=false; }
function showApp() { $('#authScreen').hidden=true; $('#app').hidden=false; }
function setAvatar(el, url, name) { el.textContent=url?'':(name?.trim()?.[0]||'•').toUpperCase(); el.style.backgroundImage=url?`url("${url}")`:''; el.style.backgroundSize='cover'; el.style.backgroundPosition='center'; }
function gateWelcome() {
  showAuth(); setAuth(`<h1>Свои —<br>в одном месте.</h1><p class="intro">Общайтесь, делитесь семейными моментами и сохраняйте их в кругу близких.</p><div class="choice-stack"><button class="choice" data-choice="create"><span class="choice-icon">✳</span><span><b>Создать круг близких</b><small>Дайте ему имя и пригласите родных</small></span><span class="choice-arrow">→</span></button><button class="choice" data-choice="join"><span class="choice-icon">⌑</span><span><b>Присоединиться</b><small>Введите код, который вам передали</small></span><span class="choice-arrow">→</span></button></div><p class="intro" style="font-size:12px;margin-top:20px">Уже есть аккаунт? <button class="auth-alt" data-login>Войти</button></p>`);
  $('#authStep').onclick=e=>{const c=e.target.closest('[data-choice]'); if(c) choosePath(c.dataset.choice); if(e.target.closest('[data-login]')) {authIntent={mode:'login'};localStorage.setItem(pendingKey,JSON.stringify(authIntent));authScreenEmail(false)}};
}
function choosePath(mode) { authIntent={mode}; localStorage.setItem(pendingKey,JSON.stringify(authIntent)); if(mode==='join') setAuth(`<button class="back" data-back>← Назад</button><p class="eyebrow">ПРИСОЕДИНЕНИЕ</p><h1>Код семейного круга</h1><p class="intro">Пригласите сюда родных с любой стороны семьи — тёть, дядей, бабушек и дедушек. Попросите близкого поделиться кодом в разделе «Семья».</p><label class="field-label">Код приглашения<input id="inviteInput" class="code-input" maxlength="24" autocomplete="off" placeholder="24 символа"></label><button id="continueInvite" class="primary full">Продолжить</button>`,38); else setAuth(`<button class="back" data-back>← Назад</button><p class="eyebrow">НОВОЕ ОБЩЕЕ МЕСТО</p><h1>Как назовём наш круг?</h1><p class="intro">Сюда можно пригласить всех близких — независимо от фамилии или стороны семьи. Можно оставить предложенное название «Наши близкие».</p><label class="field-label">Название пространства<input id="familyNameInput" maxlength="60" autocomplete="organization" value="Наши близкие" placeholder="Например, Наши близкие"></label><button id="continueCreate" class="primary full">Дальше</button>`,35); bindIntentScreen(); }
function bindIntentScreen(){ $('#authStep').onclick=e=>{if(e.target.closest('[data-back]')) {gateWelcome();return} if(e.target.closest('#continueInvite')) { const code=$('#inviteInput').value.trim().toUpperCase(); if(code.replace(/[^A-Z0-9]/g,'').length<16){toast('Проверьте код приглашения');return} authIntent.code=code;localStorage.setItem(pendingKey,JSON.stringify(authIntent));chooseAccountMode();return } if(e.target.closest('#continueCreate')) {const name=$('#familyNameInput').value.trim()||'Наши близкие';if(name.length<2){toast('Введите название семьи');return}authIntent.familyName=name;localStorage.setItem(pendingKey,JSON.stringify(authIntent));chooseAccountMode();} }; }
async function completeFamilyIntent(displayName,username){
  if(!session||!authIntent||!['create','join'].includes(authIntent.mode))return;
  username=String(username||authIntent.username||session.user.user_metadata?.username||'').trim().toLowerCase();
  if(!/^[a-z0-9_]{3,20}$/.test(username)){toast('Логин: 3–20 латинских букв, цифр или _');return}
  const {error:metadataError}=await sb.auth.updateUser({data:{username}});if(metadataError){toast(metadataError.message);return}
  const {data:existing,error:lookupError}=await sb.from('profiles').select('id').eq('id',session.user.id).maybeSingle();
  if(lookupError){toast(lookupError.message);return}
  if(existing){localStorage.removeItem(pendingKey);await start();return}
  const request=authIntent.mode==='create'
    ? sb.functions.invoke('create-family',{body:{name:authIntent.familyName||'Наши близкие',display_name:displayName,username}})
    : sb.functions.invoke('join-family',{body:{invite_code:authIntent.code,display_name:displayName,username}});
  const {data,error}=await request;
  if(error){toast(await functionError(error));return}
  localStorage.removeItem(pendingKey);
  await sb.auth.updateUser({data:{family_setup:null}}).catch(()=>{});
  authIntent=null;
  await start();
}
function chooseAccountMode(){
  if(session&&authIntent?.mode&&authIntent.mode!=='login'){
    const savedName=authIntent.displayName||session.user.user_metadata?.display_name||'';
    const savedUsername=authIntent.username||session.user.user_metadata?.username||'';
    if(savedName&&savedUsername){completeFamilyIntent(savedName,savedUsername);return}
    setAuth('<button class="back" data-back>← Назад</button><p class="eyebrow">ВАШ ПРОФИЛЬ</p><h1>Как вас называть?</h1><label class="field-label">Логин<input id="usernameInput" maxlength="20" autocomplete="username" placeholder="например, anya_7"></label><label class="field-label">Имя для близких<input id="displayNameInput" maxlength="60" autocomplete="name" placeholder="Ваше имя"></label><button id="continueWithSession" class="primary full">Продолжить</button>',82);
    $('#authStep').onclick=e=>{if(e.target.closest('[data-back]')){choosePath(authIntent.mode);return}if(e.target.closest('#continueWithSession')){const name=$('#displayNameInput').value.trim(),username=$('#usernameInput').value.trim().toLowerCase();if(name.length<2){toast('Введите имя');return}if(!/^[a-z0-9_]{3,20}$/.test(username)){toast('Логин: 3–20 латинских букв, цифр или _');return}authIntent.displayName=name;authIntent.username=username;localStorage.setItem(pendingKey,JSON.stringify(authIntent));completeFamilyIntent(name,username)}};
    return;
  }
  setAuth(`<button class="back" data-back>← Назад</button><p class="eyebrow">ВАШ АККАУНТ</p><h1>Как продолжить?</h1><p class="intro">Выберите, входили ли вы раньше в это приложение.</p><div class="choice-stack"><button class="choice" data-auth-mode="signup"><span class="choice-icon">✳</span><span><b>Создать аккаунт</b><small>Логин, имя и пароль</small></span><span class="choice-arrow">→</span></button><button class="choice" data-auth-mode="login"><span class="choice-icon">↗</span><span><b>У меня уже есть аккаунт</b><small>Войти по логину и паролю</small></span><span class="choice-arrow">→</span></button></div>`,72);
  $('#authStep').onclick=e=>{if(e.target.closest('[data-back]')){gateWelcome();return}const mode=e.target.closest('[data-auth-mode]')?.dataset.authMode;if(mode)authScreenEmail(mode==='signup')};
}
function authScreenEmail(signup=true) {
  showAuth();
  setAuth(`<button class="back" data-back>← Назад</button><p class="eyebrow">${signup?'РЕГИСТРАЦИЯ':'С ВОЗВРАЩЕНИЕМ'}</p><h1>${signup?'Начнём с вас':'Войти в свой аккаунт'}</h1><p class="intro">${signup?'Придумайте уникальный логин, имя и пароль. Почта не нужна.':'Введите логин и пароль.'}</p>${signup?'<label class="field-label">Логин<input id="usernameInput" maxlength="20" autocomplete="username" autocapitalize="none" placeholder="например, anya_7"><small class="muted">3–20 символов: латинские буквы, цифры и _</small></label><label class="field-label">Имя в приложении<input id="displayNameInput" maxlength="60" autocomplete="name" placeholder="Например, Аня"></label>':'<label class="field-label">Логин<input id="loginInput" required autocomplete="username" autocapitalize="none" placeholder="ваш логин"></label>'}<label class="field-label">Пароль<input id="passwordInput" type="password" required autocomplete="${signup?'new-password':'current-password'}" minlength="8" placeholder="Не менее 8 символов"></label><button id="submitAuth" class="primary full">${signup?'Создать аккаунт':'Войти'}</button>${signup?'':'<p class="muted">Если забыть пароль, восстановить его без почты не получится. Пока вы вошли, пароль можно сменить в настройках.</p>'}<button class="back" data-change>Изменить способ входа</button>`,signup?62:55);
  $('#authStep').onclick=async e=>{
    if(e.target.closest('[data-back]')){chooseAccountMode();return}
    if(e.target.closest('[data-change]')){authIntent=null;localStorage.removeItem(pendingKey);gateWelcome();return}
    if(!e.target.closest('#submitAuth'))return;
    const username=(signup?$('#usernameInput')?.value:$('#loginInput')?.value||'').trim().toLowerCase(),password=$('#passwordInput').value,name=$('#displayNameInput')?.value.trim()||'';
    if(!username||!password){toast('Заполните все поля');return}
    if(signup&&name.length<2){toast('Введите имя');return}
    if(signup&&!/^[a-z0-9_]{3,20}$/.test(username)){toast('Логин: 3–20 латинских букв, цифр или _');return}
    if(password.length<8){toast('Пароль должен содержать не менее 8 символов');return}
    if(!sb){toast('Подключите Supabase, чтобы включить вход');return}
    const btn=$('#submitAuth');btn.disabled=true;
    try{
      authIntent=authIntent||{mode:'login'};
      authIntent.displayName=name;authIntent.username=username;authIntent.accountMode=signup?'signup':'login';
      localStorage.setItem(pendingKey,JSON.stringify(authIntent));
      if(signup){
        const family_setup={mode:authIntent.mode,familyName:authIntent.familyName||null,code:authIntent.code||null};
        const {data,error}=await sb.functions.invoke('username-signup',{body:{username,password,display_name:name,family_setup}});
        if(error)throw error;
        if(!data?.session?.access_token||!data?.session?.refresh_token)throw new Error('Не удалось создать аккаунт. Попробуйте ещё раз.');
        const {data:sessionData,error:sessionError}=await sb.auth.setSession({access_token:data.session.access_token,refresh_token:data.session.refresh_token});if(sessionError)throw sessionError;session=sessionData.session;await start();return;
      }else{
        const {data,error}=await sb.functions.invoke('username-login',{body:{username,password}});if(error)throw error;if(!data?.session)throw new Error('Неверный логин или пароль');const {data:sessionData,error:sessionError}=await sb.auth.setSession({access_token:data.session.access_token,refresh_token:data.session.refresh_token});if(sessionError)throw sessionError;session=sessionData.session;await start();
      }
    }catch(err){const message=err.context?await functionError(err):err.message||'Не удалось продолжить';toast(/already registered|already exists|already been registered|already in use/i.test(message)?'Этот логин уже занят. Придумайте другой.':message)}
    finally{btn.disabled=false}
  };
}

function showSetNewPassword(){showAuth();setAuth(`<p class="eyebrow">ВОССТАНОВЛЕНИЕ</p><h1>Новый пароль</h1><p class="intro">Придумайте новый пароль для аккаунта.</p><label class="field-label">Новый пароль<input id="newPassword" type="password" autocomplete="new-password" minlength="8" placeholder="Не менее 8 символов"></label><button class="primary full" id="saveNewPassword">Сохранить пароль</button>`,88);$('#authStep').onclick=async e=>{if(!e.target.closest('#saveNewPassword'))return;const password=$('#newPassword').value;if(password.length<8){toast('Пароль должен содержать не менее 8 символов');return}const {error}=await sb.auth.updateUser({password});if(error){toast(error.message);return}toast('Пароль изменён');await start()}}

function restoreIntentFromAuthUser(user){const setup=user?.user_metadata?.family_setup;if(!setup||!['create','join'].includes(setup.mode))return;if(!localStorage.getItem(pendingKey))localStorage.setItem(pendingKey,JSON.stringify({mode:setup.mode,familyName:setup.familyName,code:setup.code,displayName:user.user_metadata?.display_name||'',username:user.user_metadata?.username||''}));setTimeout(()=>sb.auth.updateUser({data:{family_setup:null}}).catch(()=>{}),0);}
function configScreen(){gateWelcome();$('#authStep').insertAdjacentHTML('afterbegin','<div class="notice" role="status">Регистрация включится после подключения Supabase. Пока можно посмотреть шаги входа и создания семьи.</div>');}
async function start(){if(initTask)return initTask;initTask=(async()=>{if(!sb){configScreen();return}const {data:{session:s},error}=await sb.auth.getSession();if(error){notify(error.message);gateWelcome();return}session=s;if(!session){gateWelcome();return}const {data:existing}=await sb.from('profiles').select('id').eq('id',session.user.id).maybeSingle();let pending=null;try{pending=JSON.parse(localStorage.getItem(pendingKey)||'null')}catch{}if(existing){localStorage.removeItem(pendingKey)}else if(pending?.mode==='create'){const {data,error}=await sb.functions.invoke('create-family',{body:{name:pending.familyName,display_name:pending.displayName,username:pending.username||session.user.user_metadata?.username}});if(error){notify(`Не удалось создать семью: ${await functionError(error)}`);gateWelcome();return}localStorage.removeItem(pendingKey);toast(`Семья «${data.family?.name||pending.familyName}» создана`)}else if(pending?.mode==='join'){const {data,error}=await sb.functions.invoke('join-family',{body:{invite_code:pending.code,display_name:pending.displayName,username:pending.username||session.user.user_metadata?.username}});if(error){notify(`Не удалось присоединиться: ${await functionError(error)}`);gateWelcome();return}localStorage.removeItem(pendingKey);toast(`Вы присоединились к семье «${data.family?.name||''}»`)}else if(pending?.mode==='login'){localStorage.removeItem(pendingKey)}await hydrate()})();try{return await initTask}finally{initTask=null}}
async function functionError(error){try{const c=error.context;if(c?.json){const j=await c.json();return j.error||j.message||error.message}}catch{}return error.message}
async function hydrate(){ if(!session)return;const {data:p,error}=await sb.from('profiles').select('id,family_id,display_name,username,avatar_path,cover_path,notifications_enabled').eq('id',session.user.id).maybeSingle();if(error){gateWelcome();notify(error.message);return}if(!p){gateWelcome();if(!localStorage.getItem(pendingKey))notify('Аккаунт пока не связан с семьёй. Создайте новую семью или введите код приглашения.');return}profile=p;const {data:f,error:fe}=await sb.from('families').select('id,name,invite_code,owner_id').eq('id',p.family_id).single();if(fe){gateWelcome();notify('Не удалось загрузить семейный круг.');return}family=f;await loadMembers();await loadAvatar(profile.avatar_path,'profileAvatar');await loadAvatar(profile.avatar_path,'headerAvatar');await loadAvatar(profile.avatar_path,'composeAvatar');$('#profileName').textContent=p.display_name||'Участник';$('#profileEmail').textContent=`@${p.username}`;$('#profileBio').textContent='Вы часть «'+family.name+'».';$('#familyName').textContent=family.name;$('#inviteCode').textContent=family.invite_code;$('#notificationsEnabled').checked=profile.notifications_enabled!==false;renderPushStatus();await loadCover();showApp();activateView(routeFromHash());await loadFeed();await loadChats();await loadAvatarHistory();subscribeRealtime();}
async function loadMembers(){const {data,error}=await sb.from('profiles').select('id,display_name,avatar_path').eq('family_id',profile.family_id).order('created_at');if(error){notify(error.message);return}members=data||[];$('#members').innerHTML=members.map(m=>`<div class="member-row"><span class="avatar" data-user-avatar="${m.id}">${escapeHtml(m.display_name?.[0]||'•')}</span><span><b>${escapeHtml(m.display_name||'Участник')}</b><small>${m.id===family.owner_id?'Создатель семьи':'Участник'}</small></span></div>`).join('')||'<p class="empty-hint">Пока вы здесь одни.</p>';$('#memberCount').textContent=members.length;for(const m of members)await loadAvatar(m.avatar_path,`member-${m.id}`);}
async function signed(path,expires=3600){if(!path)return null;const {data,error}=await sb.storage.from('family-media').createSignedUrl(path,expires);return error?null:data.signedUrl}
async function loadAvatar(path,id){let el=id.startsWith('member-')?document.querySelector(`[data-user-avatar="${id.slice(7)}"]`):$('#'+id);if(!el)return;const url=await signed(path);const memberName=id.startsWith('member-')?members.find(m=>m.id===id.slice(7))?.display_name:profile?.display_name;setAvatar(el,url,memberName||el.textContent);}
function routeFromHash(){const route=location.hash.replace(/^#\/?/,'');return views[route]?route:'feed'}
function activateView(id){if(!views[id])id='feed';$$('.view,.nav,.mobile-nav button').forEach(e=>e.classList.remove('active'));$('#'+id).classList.add('active');$$(`[data-view="${id}"]`).forEach(e=>e.classList.add('active'));$('#sectionHint').textContent=views[id][0];$('#sectionTitle').textContent=views[id][1];window.scrollTo({top:0,behavior:'smooth'});return id}
function showView(id,{reload=true}={}){if(!profile){gateWelcome();return}id=activateView(id);const hash=`#/${id}`;if(location.hash!==hash)history.pushState({view:id},'',hash);if(reload&&id==='feed')loadFeed();if(reload&&id==='chats')loadChats();}
window.addEventListener('hashchange',()=>{if(!profile)return;const id=activateView(routeFromHash());if(id==='feed')loadFeed();if(id==='chats')loadChats()});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$$('[data-view="family"] span,[data-view="family"] small').forEach(label=>{label.textContent='Наш круг'});
async function loadFeed(){
  if(!profile)return false;
  const root=$('#posts');
  const {data:posts,error}=await sb.from('posts').select('id,family_id,author_id,body,image_path,created_at').eq('family_id',profile.family_id).order('created_at',{ascending:false}).limit(50);
  if(error){console.error('Feed posts query failed',error);root.innerHTML=`<div class="empty card"><h2>Ленту не удалось загрузить</h2><p>${escapeHtml(error.message)}</p></div>`;return false}
  if(!posts?.length){root.innerHTML='<div class="empty card"><span class="empty-icon">✳</span><h2>Место для ваших историй</h2><p>Пока здесь тихо. Пусть первой записью станет маленький момент из вашего дня.</p><button class="primary" id="firstPost">Создать первую запись</button></div>';$('#firstPost').onclick=openPost;return true}
  const postIds=posts.map(p=>p.id);
  const [likesResult,commentsResult]=await Promise.all([
    sb.from('post_likes').select('post_id,user_id').in('post_id',postIds),
    sb.from('comments').select('id,post_id,author_id,body,created_at').in('post_id',postIds).order('created_at')
  ]);
  if(likesResult.error)console.warn('Could not load post likes',likesResult.error);
  if(commentsResult.error)console.warn('Could not load post comments',commentsResult.error);
  const likes=likesResult.data||[],comments=commentsResult.data||[];
  const profileIds=[...new Set([...posts.map(p=>p.author_id),...comments.map(c=>c.author_id)])];
  const {data:people,error:peopleError}=await sb.from('profiles').select('id,display_name,avatar_path').in('id',profileIds);
  if(peopleError)console.warn('Could not load post authors',peopleError);
  const peopleById=new Map((people||[]).map(p=>[p.id,p]));
  const likesByPost=new Map(),commentsByPost=new Map();
  for(const like of likes)likesByPost.set(like.post_id,[...(likesByPost.get(like.post_id)||[]),like]);
  for(const comment of comments)commentsByPost.set(comment.post_id,[...(commentsByPost.get(comment.post_id)||[]),comment]);
  root.innerHTML='';
  for(const post of posts){
    const author=peopleById.get(post.author_id),postLikes=likesByPost.get(post.id)||[],postComments=commentsByPost.get(post.id)||[];
    const liked=postLikes.some(x=>x.user_id===session.user.id),avatar=await signed(author?.avatar_path),image=await signed(post.image_path);
    const article=document.createElement('article');article.className='post card';article.dataset.id=post.id;
    article.innerHTML=`<div class="post-head"><span class="avatar" style="${avatar?`background-image:url('${avatar}');background-size:cover`:''}">${avatar?'':escapeHtml(author?.display_name?.[0]||'•')}</span><div><b>${escapeHtml(author?.display_name||'Участник')}</b><small>${new Date(post.created_at).toLocaleString('ru-RU',{dateStyle:'medium',timeStyle:'short'})}</small></div></div>${post.body?`<p>${escapeHtml(post.body).replace(/\n/g,'<br>')}</p>`:''}${image?`<img class="post-image" src="${image}" alt="Фото в публикации">`:''}<div class="post-actions"><button class="like ${liked?'liked':''}" data-like="${post.id}">${liked?'♥':'♡'} ${postLikes.length}</button><button data-focus-comment="${post.id}">Ответить · ${postComments.length}</button></div><div class="comments">${postComments.map(c=>`<p><b>${escapeHtml(peopleById.get(c.author_id)?.display_name||'Участник')}</b> ${escapeHtml(c.body)}</p>`).join('')}<form class="comment-form" data-comment="${post.id}"><input name="body" maxlength="2000" placeholder="Написать комментарий…" required><button>Отправить</button></form></div>`;
    root.append(article);
  }
  root.onclick=async e=>{const like=e.target.closest('[data-like]');if(like){const postId=like.dataset.like;const was=like.classList.contains('liked');const result=was?await sb.from('post_likes').delete().eq('post_id',postId).eq('user_id',session.user.id):await sb.from('post_likes').insert({post_id:postId,user_id:session.user.id});if(result.error)toast(result.error.message);else loadFeed()}const focus=e.target.closest('[data-focus-comment]');if(focus)root.querySelector(`[data-comment="${focus.dataset.focusComment}"] input`)?.focus()};
  root.querySelectorAll('.comment-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const body=new FormData(form).get('body').trim();if(!body)return;const {error}=await sb.from('comments').insert({post_id:form.dataset.comment,author_id:session.user.id,body});if(error)toast(error.message);else loadFeed()});
  return true;
}
function openPost(){if(!profile)return;postImage=null;$('#postBody').value='';$('#postPhoto').value='';$('#photoLabel').textContent='Добавить фотографию';$('#photoPreview').hidden=true;$('#postDialog').showModal()}
$('#newPost').onclick=openPost;$('#firstPost').onclick=openPost;$('#addPhoto').onclick=openPost;$('#profileNewPost').onclick=openPost;$('#postPhoto').onchange=()=>{const f=$('#postPhoto').files?.[0];if(!f)return;postImage=f;$('#photoLabel').textContent=f.name;$('#photoPreview').innerHTML=`<img src="${URL.createObjectURL(f)}" alt="Предпросмотр">`;$('#photoPreview').hidden=false};$('#publishPost').onclick=async()=>{const body=$('#postBody').value.trim();if(!body&&!postImage){toast('Добавьте текст или фото');return}const button=$('#publishPost');button.disabled=true;try{let image_path=null;if(postImage){const ext=(postImage.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'');image_path=`${family.id}/${session.user.id}/${crypto.randomUUID()}.${ext}`;const {error}=await sb.storage.from('family-media').upload(image_path,postImage,{upsert:false,contentType:postImage.type});if(error)throw error}const {error}=await sb.from('posts').insert({family_id:family.id,author_id:session.user.id,body,image_path});if(error)throw error;$('#postDialog').close();const refreshed=await loadFeed();showView('feed',{reload:false});toast(refreshed?'Запись добавлена в ленту':'Запись создана, но ленту не удалось обновить — попробуйте открыть её позже')}catch(e){toast(e.message||'Не удалось опубликовать')}finally{button.disabled=false}};
async function loadChats(){if(!profile)return;const {data,error}=await sb.from('chat_members').select('chat_id,chats(id,title,kind,family_id)').eq('user_id',session.user.id);if(error){$('#chatList').innerHTML='<p class="empty-hint">Не удалось загрузить чаты.</p>';return}const chats=(data||[]).map(x=>x.chats).filter(Boolean);let items=[];for(const c of chats){if(c.kind==='general')items.push({...c,label:c.title||family.name});else{const {data:other}=await sb.from('chat_members').select('user_id,profiles(display_name,avatar_path)').eq('chat_id',c.id).neq('user_id',session.user.id).maybeSingle();items.push({...c,label:other?.profiles?.display_name||'Личный чат',other:other?.profiles})}}if(!items.length){$('#chatList').innerHTML='<p class="empty-hint" style="padding:16px">Пока нет чатов. Семейный чат создаётся вместе с семьёй.</p>';return}$('#chatList').innerHTML=items.map(c=>`<button class="chat-item ${selectedChat?.id===c.id?'active':''}" data-chat-id="${c.id}"><span class="avatar">${escapeHtml(c.label[0])}</span><span class="chat-item-text"><b>${escapeHtml(c.label)}</b><small>${c.kind==='general'?'Общий семейный чат':'Личный разговор'}</small></span></button>`).join('');$('#chatList').onclick=e=>{const b=e.target.closest('[data-chat-id]');if(b)selectChat(items.find(c=>c.id===b.dataset.chatId))};if(!selectedChat){selectedChat=items[0];await selectChat(selectedChat)}}
async function selectChat(chat){selectedChat=chat;$('#dialogHead').innerHTML=`<span class="avatar">${escapeHtml(chat.label[0])}</span><span><b>${escapeHtml(chat.label)}</b><small>${chat.kind==='general'?'Общий чат семьи':'Личный чат'}</small></span>`;$('#messageInput').disabled=false;$('#messageForm .send').disabled=false;$$('.chat-item').forEach(e=>e.classList.toggle('active',e.dataset.chatId===chat.id));await loadMessages()}
async function loadMessages(){
  if(!selectedChat)return;
  const {data:messages,error}=await sb.from('messages').select('id,author_id,body,created_at').eq('chat_id',selectedChat.id).order('created_at').limit(100);
  if(error){console.error('Messages query failed',error);$('#messages').innerHTML=`<p class="empty-hint">Не удалось загрузить сообщения: ${escapeHtml(error.message)}</p>`;return}
  const authorIds=[...new Set((messages||[]).map(m=>m.author_id))];
  const {data:people,error:peopleError}=authorIds.length?await sb.from('profiles').select('id,display_name').in('id',authorIds):{data:[],error:null};
  if(peopleError)console.warn('Could not load message authors',peopleError);
  const peopleById=new Map((people||[]).map(p=>[p.id,p]));
  $('#messages').innerHTML=messages?.length?messages.map(m=>`<article class="message ${m.author_id===session.user.id?'mine':''}"><div class="bubble">${m.author_id!==session.user.id?`<b>${escapeHtml(peopleById.get(m.author_id)?.display_name||'Участник')}</b>`:''}<p>${escapeHtml(m.body)}</p><time>${new Date(m.created_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} <button data-react="${m.id}" aria-label="Поставить сердечко">♡</button></time></div></article>`).join(''):'<div class="empty-hint centered">Пока нет сообщений. Скажите своим «привет».</div>';
  $('#messages').scrollTop=$('#messages').scrollHeight;
  $('#messages').onclick=async e=>{const b=e.target.closest('[data-react]');if(!b)return;const {data:found}=await sb.from('message_reactions').select('emoji').eq('message_id',b.dataset.react).eq('user_id',session.user.id).eq('emoji','❤️').maybeSingle();const result=found?await sb.from('message_reactions').delete().eq('message_id',b.dataset.react).eq('user_id',session.user.id).eq('emoji','❤️'):await sb.from('message_reactions').insert({message_id:b.dataset.react,user_id:session.user.id,emoji:'❤️'});if(result.error)toast(result.error.message);else b.textContent=found?'♡':'♥'};
}
$('#messageForm').onsubmit=async e=>{e.preventDefault();const input=$('#messageInput'),button=$('#messageForm .send'),body=input.value.trim();if(!body)return;if(!selectedChat){toast('Сначала выберите чат');return}button.disabled=true;input.disabled=true;const messageId=crypto.randomUUID();try{const {error}=await sb.from('messages').insert({id:messageId,chat_id:selectedChat.id,author_id:session.user.id,body});if(error)throw error;input.value='';await loadMessages();sb.functions.invoke('send-message-push',{body:{message_id:messageId}}).then(({error})=>{if(error)console.warn('Push уведомление не отправлено',error)}).catch(error=>console.warn('Push уведомление не отправлено',error))}catch(error){console.error('Не удалось отправить сообщение',error);toast(`Не удалось отправить: ${error.message||'проверьте подключение и попробуйте снова'}`)}finally{button.disabled=!selectedChat;input.disabled=!selectedChat;if(selectedChat)input.focus()}};
$('#newDirect').onclick=()=>{if(!members.length)return;$('#memberChoices').innerHTML=members.filter(m=>m.id!==session.user.id).map(m=>`<button class="chat-item" data-direct="${m.id}"><span class="avatar">${escapeHtml(m.display_name?.[0]||'•')}</span><span>${escapeHtml(m.display_name||'Участник')}</span></button>`).join('')||'<p class="empty-hint">Пока кроме вас никого нет.</p>';$('#memberDialog').showModal();$('#memberChoices').onclick=async e=>{const b=e.target.closest('[data-direct]');if(!b)return;const {data,error}=await sb.rpc('open_direct_chat',{other_user_id:b.dataset.direct});if(error){toast(error.message);return}$('#memberDialog').close();await loadChats();const item=await sb.from('chats').select('id,title,kind,family_id').eq('id',data).single();if(item.data)selectChat({...item.data,label:members.find(m=>m.id===b.dataset.direct)?.display_name||'Личный чат'});showView('chats')}};
$('#copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(family.invite_code);toast('Код семьи скопирован')}catch{toast(`Код семьи: ${family.invite_code}`)}};$('#shareInvite').onclick=async()=>{const shareData={title:`Присоединиться к семье «${family.name}»`,text:`Код нашей семьи: ${family.invite_code}`};try{if(navigator.share)await navigator.share(shareData);else{await navigator.clipboard.writeText(shareData.text);toast('Текст приглашения скопирован')}}catch(e){if(e.name!=='AbortError')toast('Не удалось поделиться')}};
$('#notificationsEnabled').onchange=async e=>{const enabled=e.target.checked;const {error}=await sb.from('profiles').update({notifications_enabled:enabled}).eq('id',session.user.id);if(error){toast(error.message);e.target.checked=!enabled}else{profile.notifications_enabled=enabled;toast(enabled?'Уведомления включены':'Уведомления выключены')}};
function renderPushStatus(){const button=$('#enablePush'),status=$('#pushStatus');if(!button||!status)return;if(!('PushManager'in window)||!('serviceWorker'in navigator)||!('Notification'in window)){status.textContent='Этот браузер не поддерживает push';button.disabled=true;return}if(!CONFIG.vapidPublicKey){status.textContent='Ожидает подключения push-сервиса';button.textContent='Не настроено';button.disabled=true;return}button.disabled=false;status.textContent=Notification.permission==='granted'?'Разрешение включено на этом устройстве':Notification.permission==='denied'?'Разрешение отключено в настройках браузера':'Приходят, когда сайт закрыт';button.textContent=Notification.permission==='granted'?'Настроено':'Включить'}
function decodeVapidKey(value){const normalized=value.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(normalized.padEnd(Math.ceil(normalized.length/4)*4,'='));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
$('#enablePush').onclick=async()=>{if(!CONFIG.vapidPublicKey){toast('Push ещё не настроены для этого сайта');return}if(!('PushManager'in window)||!('serviceWorker'in navigator)){toast('Этот браузер пока не поддерживает push');return}if(/iPhone|iPad|iPod/.test(navigator.userAgent)&&!navigator.standalone){toast('На iPhone сначала добавьте сайт на экран «Домой»');return}let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){renderPushStatus();toast('Разрешите уведомления в настройках браузера');return}try{const registration=await navigator.serviceWorker.ready;const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:decodeVapidKey(CONFIG.vapidPublicKey)});const json=subscription.toJSON();const {data:existing,error:lookupError}=await sb.from('push_subscriptions').select('id').eq('endpoint',json.endpoint).maybeSingle();if(lookupError)throw lookupError;if(!existing){const {error}=await sb.from('push_subscriptions').insert({user_id:session.user.id,endpoint:json.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth});if(error)throw error}renderPushStatus();toast('Уведомления включены на этом устройстве')}catch(e){toast(e.message||'Не удалось включить уведомления')}};
$('#avatarUpload').onclick=()=>$('#avatarFile').click();$('#coverUpload').onclick=()=>$('#coverFile').click();async function uploadProfileImage(file,type){if(!file)return;const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'');const path=`${family.id}/${session.user.id}/${type}-${crypto.randomUUID()}.${ext}`;const {error:upError}=await sb.storage.from('family-media').upload(path,file,{contentType:file.type,upsert:false});if(upError){toast(upError.message);return}if(type==='avatar'){for(const storage_path of [profile.avatar_path,path].filter(Boolean)){const {error}=await sb.from('avatar_history').insert({user_id:session.user.id,storage_path});if(error){toast(error.message);return}}const {error:pe}=await sb.from('profiles').update({avatar_path:path}).eq('id',session.user.id);if(pe){toast(pe.message);return}profile.avatar_path=path;await Promise.all(['profileAvatar','headerAvatar','composeAvatar'].map(id=>loadAvatar(path,id)));loadAvatarHistory()}else{const {error}=await sb.from('profiles').update({cover_path:path}).eq('id',session.user.id);if(error){toast(error.message);return}profile.cover_path=path;const url=await signed(path);$('#coverArea').style.backgroundImage=`linear-gradient(#53614b33,#53614b33),url("${url}")`;$('#coverArea').style.backgroundSize='cover';$('#coverArea').style.backgroundPosition='center'}toast(type==='avatar'?'Фото профиля обновлено':'Обложка обновлена')}
$('#avatarFile').onchange=e=>uploadProfileImage(e.target.files?.[0],'avatar');$('#coverFile').onchange=e=>uploadProfileImage(e.target.files?.[0],'cover');async function loadAvatarHistory(){const {data,error}=await sb.from('avatar_history').select('storage_path,created_at').eq('user_id',session.user.id).order('created_at',{ascending:false});if(error)return;$('#avatarHistory').innerHTML=data?.length?'': '<span class="empty-hint">История появится после смены фото.</span>';for(const row of data||[]){const url=await signed(row.storage_path);if(url)$('#avatarHistory').insertAdjacentHTML('beforeend',`<img class="history-img" src="${url}" alt="Предыдущая аватарка">`)}}
async function loadCover(){if(!profile.cover_path)return;const url=await signed(profile.cover_path);if(url){$('#coverArea').style.backgroundImage=`linear-gradient(#53614b33,#53614b33),url("${url}")`;$('#coverArea').style.backgroundSize='cover';$('#coverArea').style.backgroundPosition='center'}}
function subscribeRealtime(){sb.channel('family:'+family.id).on('postgres_changes',{event:'*',schema:'public',table:'messages'},payload=>{if(payload.new?.chat_id===selectedChat?.id)loadMessages();else if(profile.notifications_enabled&&payload.new?.author_id!==session.user.id)toast('Новое сообщение')}).on('postgres_changes',{event:'*',schema:'public',table:'posts',filter:`family_id=eq.${family.id}`},()=>{if($('#feed').classList.contains('active'))loadFeed()}).on('postgres_changes',{event:'INSERT',schema:'public',table:'profiles',filter:`family_id=eq.${family.id}`},()=>loadMembers()).subscribe();}
async function signOut(){const registration=await navigator.serviceWorker?.getRegistration().catch(()=>null);const subscription=await registration?.pushManager?.getSubscription().catch(()=>null);if(subscription){try{await sb.from('push_subscriptions').delete().eq('endpoint',subscription.endpoint)}catch(error){console.warn('Could not remove push subscription',error)}try{await subscription.unsubscribe()}catch(error){console.warn('Could not unsubscribe push',error)}}const {error}=await sb.auth.signOut();if(error){toast(error.message||'Не удалось выйти');return}session=null;profile=null;family=null;selectedChat=null;localStorage.removeItem(pendingKey);history.replaceState({},'',location.pathname+location.search);gateWelcome()}
$('#signOut').onclick=signOut;$('#signOutSettings').onclick=signOut;$('#manageAccount').onclick=()=>{$('#currentPassword').value='';$('#newPassword').value='';$('#newPasswordConfirm').value='';$('#authDialog').showModal()};$('#changePassword').onclick=async()=>{const currentPassword=$('#currentPassword').value,newPassword=$('#newPassword').value,confirmation=$('#newPasswordConfirm').value;if(!currentPassword||!newPassword||newPassword.length<8||newPassword!==confirmation){toast('Проверьте текущий пароль и повторите новый пароль (не менее 8 символов)');return}const button=$('#changePassword');button.disabled=true;try{const {data,error}=await sb.functions.invoke('username-login',{body:{username:profile.username,password:currentPassword}});if(error)throw new Error('Текущий пароль указан неверно');const {error:setError}=await sb.auth.setSession({access_token:data.session.access_token,refresh_token:data.session.refresh_token});if(setError)throw setError;const {error:updateError}=await sb.auth.updateUser({password:newPassword});if(updateError)throw updateError;$('#authDialog').close();toast('Пароль изменён')}catch(error){toast(error.message||'Не удалось сменить пароль')}finally{button.disabled=false}};
sb?.auth.onAuthStateChange((_event,s)=>{session=s;if(_event==='PASSWORD_RECOVERY'){setTimeout(showSetNewPassword,0);return}if(s){restoreIntentFromAuthUser(s.user);setTimeout(()=>start(),0)}else if(_event==='SIGNED_OUT')gateWelcome()});
if(sb){const startData=()=>start().catch(e=>{console.error('Family app initialization failed',e);gateWelcome();notify('Не удалось загрузить профиль. Попробуйте обновить страницу.')});startData()}else configScreen();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
